stateSelector.source:
function (currentState, data) {
                var newState = currentState;
                switch (currentState) {
                    case 0 /* BaseGameSpin */:
                        if (data.isBonusTriggered()) {
                            newState = 1 /* BaseGameSpinTriggerFreeSpin */;
                        }
                        break;
                    case 3 /* BonusGameSpin */:
                        var fsData = data.getCustomData();
                        if (data.isBonusTriggered()) {
                            newState = 4 /* BonusGameSpinTrigger */;
                        }
                        else if (fsData.getSpinsRemaining() == 0 || fsData.getBGTagData().getIsMaxWin()) {
                            newState = 6 /* BonusGameEnd */;
                        }
                        break;
                    case 4 /* BonusGameSpinTrigger */:
                        newState = (data.isBonusTriggered()) ? 4 /* BonusGameSpinTrigger */ : 3 /* BonusGameSpin */;
                        break;
                    case 1 /* BaseGameSpinTriggerFreeSpin */:
                        newState = 3 /* BonusGameSpin */;
                        break;
                    case 6 /* BonusGameEnd */:
                        newState = 0 /* BaseGameSpin */;
                        break;
                    case 7 /* Recovering */:
                        if (data.getCustomData() instanceof ladyofegypt.LOEBaseGameSpinData)
                            newState = 0 /* BaseGameSpin */;
                        else
                            newState = 3 /* BonusGameSpin */;
                        break;
                    case 8 /* HistoryReplay */:
                        newState = 0 /* BaseGameSpin */;
                }
                return newState;
            }

