actualRequestDTO.source:
function (wager) {
                var payloads = [];
                var payload = new ladyofegypt.LTWagerPayload(wager.getTotalBet());
                payloads.push(payload);
                if (this.historyData != null) {
                    payloads.push(new glscomms.ReplayRequestPayload(this.historyData.getNextState()));
                }
                if (this.slot.shouldGaff()) {
                    var reelStop = this.slot.getGaffStops();
                    var Mystery = prompt("Enter Mystery", "-1");
                    var randomWild = "";
                    var jackPortIndex = "";
                    if (Mystery != -1 && Mystery !== null) {
                        reelStop = Mystery.split("|");
                    }
                    if (this.slot.getGaffingType() === 1) {
                        var randomWildPrompt = prompt("Enter Random wild comboIndex", "1");
                        randomWild = randomWildPrompt;
                    }
                    else if (this.slot.getGaffingType() === 2) {
                        var jackPrompt = prompt("Enter Jackpot comboIndex[0 , 1, 2]", "1");
                        jackPortIndex = jackPrompt;
                    }
                    payloads.push(new ladyofegypt.GaffPayload(reelStop, this.slot.getGaffReelIndex(), this.slot.getGaffingType(), this.slot.getSymbolID(), randomWild, jackPortIndex));
                }
                return payloads;
            }

