parseReply.source:
function (xml) {
                var platformData = this.parsePlatformData(xml);
                var balanceData = glscomms.BalanceData.parseXML(xml.getElementsByTagName("Balances")[0]);
                var response = new glscomms.PlayResponse(platformData, balanceData);
                // Parse custom game data
                var gameData = response.getGameData();
                var bgResultData = xml.getElementsByTagName("BaseGameRecoveryInfo");
                if (bgResultData.length > 0) {
                    var fsData = this.populateFreeGameData(xml, gameData);
                    ladyofegypt.GamePlayDataXMLParser.populateGameData(gameData, xml.getElementsByTagName("GameResult")[0]);
                    if (fsData.getSpinsAwarded() > 0) {
                        response.getGameData().setIsBonusTriggered(true);
                    }
                    else
                        response.getGameData().setIsBonusTriggered(false);
                    response.getGameData().setCustomData(fsData);
                }
                else {
                    ladyofegypt.GamePlayDataXMLParser.populateGameData(gameData, xml.getElementsByTagName("GameResult")[0]);
                    response.getGameData().setCustomData(this.populateGameCustomData(xml, gameData));
                    if (response.getGameData().getCustomData().getFreeGameInfo() !== undefined)
                        response.getGameData().setIsBonusTriggered(true);
                    else
                        response.getGameData().setIsBonusTriggered(false);
                }
                return response;
            }

parseCurrentCurrency.source:
function (xml) {
                var data = new glscomms.PlatformInitData();
                var glsHeader = glscomms.GLSResponseHeader.parseXML(xml.getElementsByTagName("Header")[0]);
                data.setSessionId(glsHeader.getSessionId());
                data.setGameId(glsHeader.getGameId());
                data.setLanguageCode(glsHeader.getLanguageCode());
                data.setVersion(glsHeader.getVersion());
                data.setIsRecovering(glsHeader.isRecovering());
                data.setCurrencyFormat(glscomms.CurrencyFormatXMLParser.parse(xml.getElementsByTagName("CurrencyInformation")[0]));
                var currencyMultiplierNode = xml.getElementsByTagName("CurrencyMultiplier")[0];
                if (currencyMultiplierNode != null) {
                    data.setCurrencyMultiplier(parseInt(currencyMultiplierNode.textContent, 10));
                }
                return data;
            }

freeFields.source:
function (xml, gameData) {
                var freeGameData;
                var node = xml.getElementsByTagName("GameResult")[0];
                var BaseGameNode = xml.getElementsByTagName("BaseGame")[0];
                var totalWin = parseInt(node.attributes.getNamedItem("totalWin").value, 10);
                var reelsNode = node.childNodes;
                var freeGameNode;
                var wildData;
                var bonus;
                for (var i = 0; i < reelsNode.length; ++i) {
                    if (reelsNode[i].nodeName == "ReelResults") {
                        var spinData = this.populateBgInfo(reelsNode[i], totalWin);
                    }
                    else if (reelsNode[i].nodeName == "BaseGameRecoveryInfo") {
                        var baseRecoveryInfo = this.populateBaseRecoveryInfo(reelsNode[i]);
                    }
                    else if (reelsNode[i].nodeName == "Feature") {
                        if (reelsNode[i].attributes.getNamedItem("name").value === "FreeSpins") {
                            freeGameNode = reelsNode[i].childNodes[0];
                        }
                        else if (reelsNode[i].attributes.getNamedItem("name").value === "RandomWild") {
                            wildData = reelsNode[i].childNodes[0];
                        }
                        else if (reelsNode[i].attributes.getNamedItem("name").value === "Jackpot") {
                            var jackPotData = this.populateJackPorInfo(reelsNode[i]);
                        }
                        else if (reelsNode[i].attributes.getNamedItem("name").value === "bonusGuarantee") {
                            bonus = reelsNode[i];
                        }
                    }
                    else if (reelsNode[i].nodeName === "BaseGame") {
                        var bgTagInfo = this.populateBGTagInfo(reelsNode[i]);
                    }
                }
                var freeGaneAwarded = parseInt(freeGameNode.attributes.getNamedItem("freeSpinsAwarded").value);
                var isLastSpin = freeGameNode.attributes.getNamedItem("lastSpin").value;
                var triggerWin = parseInt(freeGameNode.attributes.getNamedItem("triggerWin").value);
                var randomWild = wildData.textContent.split("|").map(Number);
                var isBonusAwared = false;
                var bonusAmount = 0;
                var currentSpin = parseInt(freeGameNode.attributes.getNamedItem("currentSpinNumber").value);
                var totalFreeSpin = parseInt(freeGameNode.attributes.getNamedItem("totalFreeSpinsAwarded").value);
                var freeGameTotalWin = parseInt(freeGameNode.attributes.getNamedItem("freeSpinTotalWin").value);
                var spinsRemaining = totalFreeSpin - currentSpin;
                var totalWin = parseInt(BaseGameNode.attributes.getNamedItem("totalWagerWin").value);
                if (bonus !== undefined) {
                    isBonusAwared = true;
                    bonusAmount = parseInt(bonus.attributes.getNamedItem("bonusAwarded").value);
                }
                var isLastSpinBl = (isLastSpin === "Y") ? true : false;
                var isFGFirstSpin = (currentSpin === 1) ? true : false;
                freeGameData = new ladyofegypt.LOEFreeSpinData(spinsRemaining, freeGaneAwarded, freeGameTotalWin, randomWild, isBonusAwared, bonusAmount, false, triggerWin, isLastSpinBl, isFGFirstSpin);
                freeGameData.setSpinData(spinData);
                freeGameData.setJackPotData(jackPotData);
                freeGameData.setTotalWin(totalWin);
                freeGameData.setBaseGameRecoveryInfo(baseRecoveryInfo);
                freeGameData.setBGTagData(bgTagInfo);
                var payloadNode = xml.getElementsByTagName("Payload")[0];
                if (payloadNode != null) {
                    freeGameData.setOpenBetInfo(this.populateOpenBetPayLoad(gameData, payloadNode));
                }
                else {
                    freeGameData.setOpenBetInfo(undefined);
                }
                return freeGameData;
            }

baseTriggerFields.source:
function (node, bgSpinData) {
                var index = parseInt(node.attributes.getNamedItem("index").value, 10);
                var nodes = node.childNodes;
                var dataNode = nodes[0];
                if (dataNode.attributes.length === 2) {
                    var freeGaneAwarded = parseInt(dataNode.attributes.getNamedItem("freeSpinsAwarded").value);
                    var triggerWin = parseInt(dataNode.attributes.getNamedItem("triggerWin").value);
                    bgSpinData.setFreeGameInfo(freeGaneAwarded, triggerWin);
                }
                else {
                    var freeGaneAwarded = parseInt(dataNode.attributes.getNamedItem("freeSpinsAwarded").value);
                    var triggerWin = parseInt(dataNode.attributes.getNamedItem("triggerWin").value);
                    var currentSpin = parseInt(dataNode.attributes.getNamedItem("currentSpinNumber").value);
                    var totalFreeSpin = parseInt(dataNode.attributes.getNamedItem("totalFreeSpinsAwarded").value);
                    var freeGameTotalWin = parseInt(dataNode.attributes.getNamedItem("freeSpinTotalWin").value);
                }
            }

necessaryBaseWinFields.source:
function (node) {
                var baseGameTagInfo;
                var totalWagerWin = 0;
                var bgWinAmt = 0;
                var nodeElement = node;
                nodeElement.hasAttribute("totalWagerWin");
                //dataNode.attributes.length===2
                if (nodeElement.hasAttribute("totalWagerWin")) {
                    totalWagerWin = parseInt(node.attributes.getNamedItem("totalWagerWin").value, 10);
                    bgWinAmt = parseInt(node.attributes.getNamedItem("bgWinnings").value, 10);
                }
                var isMaxWin = (node.attributes.getNamedItem("isMaxWin").value === "N") ? false : true;
                var maxWinAmt = parseInt(node.attributes.getNamedItem("maxWinValue").value, 10);
                baseGameTagInfo = new ladyofegypt.LOEBaseGameTagInfo(totalWagerWin, bgWinAmt, isMaxWin, maxWinAmt);
                return baseGameTagInfo;
            }

realEndCaller.source:
function () {
                var _this = this;
                switch (this.gameState) {
                    case 0 /* BaseGameSpin */:
                        if (this.historyData == null && !this.endSent) {
                            this.endSent = true;
                            this.slot.resetMultiplier();
                            if (this.uiController.getWin())
                                this.slot.getWinDisplayController().showMessages(0 /* BASEGAMEWIN */);
                            else
                                this.slot.getWinDisplayController().showMessages(4 /* CLEAR_MSG */);
                            this.glsRequestor.makeEndRequest();
                        }
                        break;
                    case 1 /* BaseGameSpinTriggerFreeSpin */:
                        // Bonus game triggered from base game
                        var bgData = this.getBaseGameData();
                        var reelSetIndex = this.getFreeGeemReelSet();
                        if (reelSetIndex === 5)
                            --reelSetIndex;
                        this.uiController.stopAutoPlay();
                        this.slot.getWinDisplayController().startBonusSymAnimation(reelSetIndex, bgData.getFreeGameInfo().getFreeTriggerWin());
                        this.freeGameIntro = true;
                        this.gameState = 2 /* BaseGameFreeGameIntro */;
                        break;
                    case 2 /* BaseGameFreeGameIntro */:
                        var baseGameSpinData = this.slot.getWinDisplayController().getGameResults().getCustomData();
                        this.showFGIntorBanner(baseGameSpinData.getFreeGameInfo().getFreeGameAward());
                        break;
                    case 4 /* BonusGameSpinTrigger */:
                        var freeGameSpinData = this.getFreeSpinData();
                        var reelSetIndex = this.getFreeGeemReelSet();
                        if (reelSetIndex === 5)
                            --reelSetIndex;
                        this.slot.getWinDisplayController().startBonusSymAnimation(reelSetIndex, freeGameSpinData.getFGTriggerWin());
                        this.gameState = 5 /* BonuGameRetriggerBanner */;
                        //this.gameState = GamePlayState.BonusGameSpin;
                        if (freeGameSpinData.getSpinsAwarded()) {
                            var win = this.uiController.getWin() + freeGameSpinData.getFGTriggerWin();
                            this.uiController.setWin(win);
                        }
                        break;
                    case 5 /* BonuGameRetriggerBanner */:
                        this.gameState = 3 /* BonusGameSpin */;
                        var freeGameSpinData = this.getFreeSpinData();
                        this.showFreeGameRetriggerBanner(freeGameSpinData.getSpinsAwarded());
                        this.uiController.updateFGCount(freeGameSpinData.getSpinsRemaining());
                        break;
                    case 3 /* BonusGameSpin */:
                        var freeGameSpinData = this.getFreeSpinData();
                        var fgRemaining = freeGameSpinData.getSpinsRemaining();
                        this.uiController.setSpinButtonVisible(false);
                        if (fgRemaining >= 0) {
                            this.uiController.updateFGCount(--fgRemaining);
                            if (!this.uiController.getFGGaffing()) {
                                TweenLite.delayedCall((ladyofegypt.Config.REQUEST_DELAY_TIME / 2), function () {
                                    _this.sendWager(_this.lastWager);
                                });
                            }
                        }
                        else {
                            this.glsRequestor.makeEndRequest();
                        }
                        break;
                    case 6 /* BonusGameEnd */:
                        var freeGameSpinData = this.getFreeSpinData();
                        var fsTotalWin = freeGameSpinData.getTotalFSWin() - freeGameSpinData.getBonusAmount();
                        var totalStake2x = this.uiController.getCurrentTotalStake() * 2;
                        if (fsTotalWin < 0)
                            fsTotalWin = 0;
                        if (freeGameSpinData.getBGTagData().getIsMaxWin()) {
                            this.showMaxWinBanner(freeGameSpinData.getBGTagData().getMaxWinValue());
                        }
                        else if (fsTotalWin < totalStake2x) {
                            this.fgTransitionController.stopFreeGameSound(false);
                            this.fgTransitionController.startFreeGameTransition();
                        }
                        else
                            this.showFGOutroBanner(fsTotalWin);
                        break;
                    case 7 /* Recovering */:
                        break;
                    default:
                        break;
                }
            }

freeTransitionCompleted.source:
function () {
                var totalwin;
                if (this.freeGameIntro) {
                    var bgData = this.getBaseGameData();
                    var fsRemaining = bgData.getFreeGameInfo().getFreeGameAward();
                    this.uiController.updateFGCount(--fsRemaining);
                    this.sendWager(this.lastWager);
                    this.freeGameIntro = false;
                    this.uiController.setIsFreeGame(true);
                }
                else {
                    this.slot.resetMultiplier();
                    this.slot.getWinDisplayController().showMessages(2 /* BONUS_PAY */, true);
                    var fsData = this.getFreeSpinData();
                    totalwin = fsData.getTotalWin();
                    if (fsData.getBGTagData().getIsMaxWin()) {
                        this.glsRequestor.makeEndRequest();
                        this.uiController.setWin(totalwin);
                    }
                    else if (fsData.getIsBonusGuarantee()) {
                        var that = this;
                        var amount = fsData.getBonusAmount();
                        this.fgTransitionController.showBonusGaurantBanner(amount);
                        //this.slot.getWinDisplayController().showMessages(ladyofegypt.CyclicMessage.BONUS_PAY);  
                        this.uiController.setWin(totalwin - amount);
                        setTimeout(function () {
                            if (!that.isHistoryReplay)
                                that.glsRequestor.makeEndRequest();
                            if (!that.uiController.isWinMeterShown())
                                that.uiController.playWinMeter(true, true);
                            that.uiController.setWin(fsData.getBGTagData().getTotalWagerWin());
                        }, ladyofegypt.Config.BONUS_GUARANTEE_BANNER_WAIT_TIME);
                    }
                    else {
                        if (!this.isHistoryReplay)
                            this.glsRequestor.makeEndRequest();
                        this.uiController.setWin(totalwin);
                    }
                }
            }

startFreeGame.source:
function () {
                this.fgTransitionController.removeFreeGameIntroBanner();
                if (this.fgTransitionController.getISAssetsLoaded()) {
                    this.fgTransitionController.startFreeGameTransition();
                    this.gameState = 3 /* BonusGameSpin */;
                }
                else
                    this.fgTransitionController.loadAssets();
            }
